// Primordial Aura: the effect's own "system.traits.dr.value" change grants the Resistance.
// When the creature already had Resistance to the type from another source, this macro upgrades the
// effect by adding a "system.traits.di.value" change to the effect itself. It never writes trait data
// to the actor, so removing the effect removes everything it granted.
const lastArg = args?.[args.length - 1] ?? {};
const phase = args?.[0];
if (phase !== "on") return;

const damageType = String(args?.[1] ?? lastArg.damageType ?? "").trim().toLowerCase();
if (!damageType) return;

const actorDoc = lastArg.actorUuid ? await fromUuid(lastArg.actorUuid) : (actor ?? null);
const effectDoc =
  (lastArg.effectUuid ? await fromUuid(lastArg.effectUuid) : null) ??
  actorDoc?.effects?.get?.(lastArg.effectId) ??
  null;
if (!actorDoc || !effectDoc) return;

const DR_KEY = "system.traits.dr.value";
const DI_KEY = "system.traits.di.value";
const toArray = value => {
  if (Array.isArray(value)) return [...value];
  if (value instanceof Set) return [...value];
  return [];
};
const splitValues = value => String(value ?? "").split(/[\s,;]+/).map(v => v.trim().toLowerCase()).filter(Boolean);
const otherEffectGrants = key =>
  (actorDoc.appliedEffects ?? []).some(effect =>
    effect.id !== effectDoc.id &&
    (effect.changes ?? []).some(change => change.key === key && splitValues(change.value).includes(damageType))
  );

if ((effectDoc.changes ?? []).some(change => change.key === DI_KEY)) return;

const alreadyImmune = toArray(actorDoc.system?.traits?.di?.value).includes(damageType);
if (alreadyImmune) return;

const sourceResistant = toArray(actorDoc._source?.system?.traits?.dr?.value).includes(damageType);
const alreadyResistant = sourceResistant || otherEffectGrants(DR_KEY);
if (!alreadyResistant) return;

try {
  await effectDoc.update({
    changes: [
      ...effectDoc.changes.map(change => ({ ...change })),
      { key: DI_KEY, mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: damageType, priority: 20 }
    ]
  });
} catch (error) {
  console.warn("Primordial Aura | could not upgrade Resistance to Immunity", error);
}

expect:
const lastArg = args?.[args.length - 1] ?? {};
const phase = args?.[0];
const passedType =
  args?.[1] ??
  lastArg.damageType ??
  item?.getFlag("world", "damageType") ??
  null;

const damageType = String(passedType ?? "").trim().toLowerCase();
if (!damageType) {
  ui.notifications.warn("No damage type was provided to the Item Macro.");
  return;
}

const actorDoc =
  lastArg.actorUuid ? await fromUuid(lastArg.actorUuid) :
  item?.actor ??
  actor ??
  token?.actor ??
  null;

if (!actorDoc) {
  ui.notifications.warn("No actor found for resistance/immunity macro.");
  return;
}

// This macro assumes standard dnd5e trait structure.
// If your install differs, inspect actorDoc.system.traits in console.
const drPath = "system.traits.dr.value";
const diPath = "system.traits.di.value";

const toArray = (value) => {
  if (Array.isArray(value)) return [...value];
  if (value instanceof Set) return [...value];
  if (value?.values && typeof value.values === "function") return [...value.values()];
  return [];
};

const unique = (arr) => [...new Set(arr)];
const hasType = (arr, type) => arr.includes(type);

const currentRes = toArray(foundry.utils.getProperty(actorDoc, drPath));
const currentImm = toArray(foundry.utils.getProperty(actorDoc, diPath));

const effectId =
  lastArg.effectId ??
  lastArg.efData?._id ??
  "noEffect";

const stateKey = `${item?.uuid ?? "noItem"}::${effectId}::${damageType}`;
const stateFlagKey = "resistanceImmunityState";
const storedState = actorDoc.getFlag("world", stateFlagKey) ?? {};

if (phase === "off") {
  const prior = storedState[stateKey];
  if (!prior) return;

  const res = toArray(foundry.utils.getProperty(actorDoc, drPath));
  const imm = toArray(foundry.utils.getProperty(actorDoc, diPath));

  if (prior.mode === "resistance") {
    const newRes = res.filter(t => t !== damageType);
    await actorDoc.update({
      [drPath]: newRes
    });
  } else if (prior.mode === "immunity") {
    const newImm = imm.filter(t => t !== damageType);
    await actorDoc.update({
      [diPath]: newImm
    });
  }

  delete storedState[stateKey];
  await actorDoc.setFlag("world", stateFlagKey, storedState);
  return;
}

// Default behavior: treat anything other than "off" as apply/on
if (hasType(currentImm, damageType)) {
  // Actor already has immunity, so do nothing and track nothing.
  return;
}

if (hasType(currentRes, damageType)) {
  // Already resistant -> grant immunity
  const newImm = unique([...currentImm, damageType]);

  await actorDoc.update({
    [diPath]: newImm
  });

  storedState[stateKey] = {
    mode: "immunity",
    damageType
  };
  await actorDoc.setFlag("world", stateFlagKey, storedState);
} else {
  // No resistance -> grant resistance
  const newRes = unique([...currentRes, damageType]);

  await actorDoc.update({
    [drPath]: newRes
  });

  storedState[stateKey] = {
    mode: "resistance",
    damageType
  };
  await actorDoc.setFlag("world", stateFlagKey, storedState);
}
